-- KylinOps 自定义工具预置数据 (PostgreSQL)
-- 生成时间(UTC): 2026-06-13 14:00:43
-- 工具数量: 8
--
-- 工具列表:
--   check_account_lock_status      L1  账户锁定检查
--   check_console_access_available L1  控制台访问确认
--   check_ssh_connectivity         L1  SSH 连通性
--   get_password_policy            L1  密码策略
--   get_user_account_info          L1  账户信息
--   get_password_recovery_playbook L1  离线恢复手册
--   verify_account_after_reset     L2  改密后验证
--   reset_user_password            L5  在线改密（需审批）
--
-- 重复执行安全：已存在同名工具时自动跳过

-- 用法:
--   psql -U postgres -d yunwei -f deploy/sql/tool_configs.postgresql.sql

-- check_account_lock_status (../../tools/custom/password_recovery/check_account_lock_status.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('ee3753d47046', 'check_account_lock_status', '生成 faillock / pam_tally2 检查命令，判断账户是否因多次输错密码被锁定。若仅锁定而非遗忘密码，优先解锁而非重置。', 'system_operation', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：check_account_lock_status — 检查账户是否被 PAM 锁定\"\"\"\nNAME = \"check_account_lock_status\"\nDESCRIPTION = (\n    \"生成 faillock / pam_tally2 检查命令，判断账户是否因多次输错密码被锁定。\"\n    \"若仅锁定而非遗忘密码，优先解锁而非重置。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\"username\": \"kylin\"}\n\n\ndef _cmds(username: str):\n    u = username.replace(\"''\", \"\")\n    return [\n        {\"command\": f\"faillock --user {u} 2>/dev/null || echo ''faillock-not-installed''\", \"purpose\": \"faillock 锁定记录（较新系统）\"},\n        {\"command\": f\"pam_tally2 --user {u} 2>/dev/null || echo ''pam_tally2-not-installed''\", \"purpose\": \"pam_tally2 失败次数（旧系统）\"},\n        {\"command\": f\"grep -E ''^{u}:'' /etc/shadow 2>/dev/null | cut -d: -f2 | head -c 20 || echo ''no-shadow-access''\", \"purpose\": \"shadow 状态抽样（!! 表示锁定，无直接改密）\"},\n    ]\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"\").strip()\n    if not username:\n        return {\"success\": False, \"error\": \"请提供 username 参数\"}\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"username\": username,\n            \"commands\": _cmds(username),\n            \"unlock_commands\": [\n                {\"command\": f\"faillock --user {username} --reset\", \"purpose\": \"解除 faillock 锁定\", \"risk\": \"L3\"},\n                {\"command\": f\"pam_tally2 --user {username} --reset\", \"purpose\": \"重置 pam_tally2 计数\", \"risk\": \"L3\"},\n            ],\n            \"decision_rules\": {\n                \"locked\": \"优先执行 unlock_commands 后让用户重试原密码\",\n                \"not_locked\": \"继续 get_password_policy → reset_user_password 流程\",\n            },\n            \"agent_instruction\": \"先执行检查命令；若锁定则解锁并告知用户，勿急于改密\",\n            \"trial_simulated\": {\"username\": username, \"locked\": False, \"fail_count\": 0},\n            \"summary\": f\"已生成用户「{username}」账户锁定状态检查方案\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- check_console_access_available (../../tools/custom/password_recovery/check_console_access_available.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('e4b6cb7ceb14', 'check_console_access_available', '询问并记录用户是否拥有目标虚拟机控制台访问能力（VMware/VirtualBox/VNC/物理显示器/IPMI）。离线密码恢复（GRUB/LiveCD）必须在控制台操作，本工具用于分支判断：仅指引或可走在线改密。', 'system_operation', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：check_console_access_available — 确认是否有虚拟机控制台\"\"\"\nNAME = \"check_console_access_available\"\nDESCRIPTION = (\n    \"询问并记录用户是否拥有目标虚拟机控制台访问能力（VMware/VirtualBox/VNC/物理显示器/IPMI）。\"\n    \"离线密码恢复（GRUB/LiveCD）必须在控制台操作，本工具用于分支判断：仅指引或可走在线改密。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\n    \"has_console\": True,\n    \"console_type\": \"vmware\",\n    \"target_host\": \"192.168.1.100\",\n}\n\nCONSOLE_TYPES = {\n    \"vmware\": \"VMware Workstation / ESXi 控制台\",\n    \"virtualbox\": \"VirtualBox 图形控制台\",\n    \"vnc\": \"VNC / 远程 KVM\",\n    \"physical\": \"物理机显示器 + 键盘\",\n    \"ipmi\": \"IPMI / iLO / iDRAC 带外\",\n    \"unknown\": \"未明确\",\n}\n\n\ndef run(**kwargs):\n    has_console = kwargs.get(\"has_console\")\n    if has_console is None:\n        has_console = kwargs.get(\"console_available\")\n    console_type = (kwargs.get(\"console_type\") or \"unknown\").strip().lower()\n    target_host = (kwargs.get(\"target_host\") or kwargs.get(\"host\") or \"\").strip()\n    notes = (kwargs.get(\"notes\") or \"\").strip()\n\n    if has_console is None:\n        return {\n            \"success\": False,\n            \"error\": \"请提供 has_console（true/false）表示用户是否能打开虚拟机控制台\",\n        }\n\n    has_console = bool(has_console)\n    label = CONSOLE_TYPES.get(console_type, CONSOLE_TYPES[\"unknown\"])\n\n    if has_console:\n        route = \"offline_playbook\"\n        summary = f\"用户具备控制台访问（{label}），可走 GRUB/救援/LiveCD 离线恢复流程\"\n        next_tools = [\"get_password_recovery_playbook\"]\n        warnings = []\n    else:\n        route = \"online_or_escalate\"\n        summary = \"用户无控制台访问，无法执行 GRUB/LiveCD 离线改密，需尝试 SSH 在线改密或联系机房带外\"\n        next_tools = [\"check_ssh_connectivity\", \"reset_user_password\"]\n        warnings = [\"离线恢复必须在控制台完成，Agent 无法远程代替按键操作\"]\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"target_host\": target_host,\n            \"has_console\": has_console,\n            \"console_type\": console_type,\n            \"console_label\": label,\n            \"notes\": notes,\n            \"recommended_route\": route,\n            \"next_tools\": next_tools,\n            \"warnings\": warnings,\n            \"agent_questions\": [\n                \"您是否能打开该虚拟机的控制台窗口（VMware/VirtualBox/物理屏幕）？\",\n                \"控制台类型是 VMware、VirtualBox、VNC 还是物理机？\",\n            ],\n            \"summary\": summary,\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- check_ssh_connectivity (../../tools/custom/password_recovery/check_ssh_connectivity.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('3c3cb81c7617', 'check_ssh_connectivity', '生成在目标麒麟 VM 上检测 SSH 连通性的命令集与判定规则。用于决定走「在线 reset_user_password」还是「离线 get_password_recovery_playbook」流程。', 'system_monitor', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：check_ssh_connectivity — 检测目标 VM SSH 连通性与登录账号\"\"\"\nNAME = \"check_ssh_connectivity\"\nDESCRIPTION = (\n    \"生成在目标麒麟 VM 上检测 SSH 连通性的命令集与判定规则。\"\n    \"用于决定走「在线 reset_user_password」还是「离线 get_password_recovery_playbook」流程。\"\n)\nCATEGORY = \"system_monitor\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\"host\": \"192.168.1.100\", \"port\": 22, \"ssh_user\": \"root\"}\n\nREMOTE_COMMANDS = [\n    {\"command\": \"whoami\", \"purpose\": \"确认当前 SSH 登录账号\"},\n    {\"command\": \"hostname\", \"purpose\": \"确认目标主机名\"},\n    {\"command\": \"echo kylinops-ssh-ok\", \"purpose\": \"连通性探针\"},\n    {\"command\": \"getent passwd root | cut -d: -f1,3,6,7\", \"purpose\": \"确认 root 账户存在\"},\n]\n\n\ndef run(**kwargs):\n    host = (kwargs.get(\"host\") or kwargs.get(\"target_host\") or \"\").strip()\n    port = int(kwargs.get(\"port\") or 22)\n    ssh_user = (kwargs.get(\"ssh_user\") or kwargs.get(\"username\") or \"root\").strip()\n\n    route_online = {\n        \"condition\": \"SSH 可达且为 root 或具备 sudo passwd 权限的运维账号\",\n        \"next_tools\": [\n            \"get_user_account_info\",\n            \"check_account_lock_status\",\n            \"get_password_policy\",\n            \"reset_user_password\",\n            \"verify_account_after_reset\",\n        ],\n    }\n    route_offline = {\n        \"condition\": \"SSH 不可达或仅有目标用户自身凭证且已遗忘\",\n        \"next_tools\": [\"check_console_access_available\", \"get_password_recovery_playbook\"],\n    }\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"target\": {\"host\": host, \"port\": port, \"ssh_user\": ssh_user},\n            \"commands\": REMOTE_COMMANDS,\n            \"agent_instruction\": (\n                \"先确认 KylinOps 已绑定目标服务器且 SSH 连接成功；\"\n                \"再对目标 VM 通过 execute_command 执行 commands 列表；\"\n                \"若全部成功则走 online 流程，否则走 offline 流程。\"\n            ),\n            \"decision_rules\": {\n                \"ssh_ok\": route_online,\n                \"ssh_fail\": route_offline,\n            },\n            \"trial_simulated\": {\n                \"ssh_reachable\": True,\n                \"logged_in_as\": ssh_user,\n                \"recommended_route\": \"online\",\n            },\n            \"summary\": f\"已生成 SSH 连通性检查方案（目标 {host or ''已选服务器''}:{port}，账号 {ssh_user}）\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- get_password_policy (../../tools/custom/password_recovery/get_password_policy.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('13e6cb46c134', 'get_password_policy', '生成读取 pwquality.conf、login.defs 及用户 chage 信息的命令，用于重置密码时生成符合策略的临时密码并提示用户规则。', 'system_operation', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：get_password_policy — 读取系统密码复杂度策略\"\"\"\nNAME = \"get_password_policy\"\nDESCRIPTION = (\n    \"生成读取 pwquality.conf、login.defs 及用户 chage 信息的命令，\"\n    \"用于重置密码时生成符合策略的临时密码并提示用户规则。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\"username\": \"kylin\"}\n\nREMOTE_COMMANDS = [\n    {\"command\": \"cat /etc/security/pwquality.conf 2>/dev/null | grep -v ''^#'' | grep -v ''^$'' || echo ''no-pwquality''\", \"purpose\": \"密码复杂度（长度、字符类、字典检查）\"},\n    {\"command\": \"grep -E ''^PASS_(MAX|MIN|WARN)_DAYS'' /etc/login.defs 2>/dev/null || echo ''no-login-defs''\", \"purpose\": \"密码有效期策略\"},\n    {\"command\": \"grep -E ''^ENCRYPT_METHOD'' /etc/login.defs 2>/dev/null || echo ''ENCRYPT_METHOD-SHA512''\", \"purpose\": \"加密算法\"},\n]\n\nDEFAULT_POLICY = {\n    \"minlen\": 8,\n    \"minclass\": 3,\n    \"hints\": [\n        \"建议临时密码 ≥8 位，含大小写字母、数字、特殊字符中的至少 3 类\",\n        \"重置后提示用户首次登录立即修改\",\n        \"禁止使用与用户名相同或连续键盘序列\",\n    ],\n}\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"\").strip()\n    cmds = list(REMOTE_COMMANDS)\n    if username:\n        u = username.replace(\"''\", \"\")\n        cmds.append({\n            \"command\": f\"chage -l {u} 2>/dev/null || echo ''chage-not-available''\",\n            \"purpose\": f\"用户 {username} 的密码过期信息\",\n        })\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"username\": username or None,\n            \"commands\": cmds,\n            \"default_policy\": DEFAULT_POLICY,\n            \"temp_password_template\": \"Kylin@{uid_last4}!{rand2}\",\n            \"agent_instruction\": (\n                \"执行 commands 解析 minlen/minclass 等；\"\n                \"生成临时密码时遵守策略并仅通过安全渠道一次性交付用户\"\n            ),\n            \"trial_simulated\": {\n                \"minlen\": 8,\n                \"minclass\": 3,\n                \"encrypt_method\": \"SHA512\",\n            },\n            \"summary\": \"已生成密码策略读取命令与临时密码生成建议\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- get_password_recovery_playbook (../../tools/custom/get_password_recovery_playbook.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('623732319496', 'get_password_recovery_playbook', '当用户忘记麒麟虚拟机登录密码且无法 SSH 在线改密时，按系统类型（桌面/服务器）与恢复方式（GRUB 单用户、救援模式、LiveCD）生成分步操作手册，供用户在虚拟机控制台手动执行。', 'system_operation', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"\nKylinOps 自定义工具：get_password_recovery_playbook\n按系统类型生成麒麟虚拟机「忘记密码」离线恢复操作手册。\n\n知识库来源：\n  - 6.1 用户密码忘记/无法登录（SEC-001）\n  - 常见-登录问题 / 忘记用户密码\n\"\"\"\nNAME = \"get_password_recovery_playbook\"\nDESCRIPTION = (\n    \"当用户忘记麒麟虚拟机登录密码且无法 SSH 在线改密时，\"\n    \"按系统类型（桌面/服务器）与恢复方式（GRUB 单用户、救援模式、LiveCD）\"\n    \"生成分步操作手册，供用户在虚拟机控制台手动执行。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\n    \"username\": \"kylin\",\n    \"system_type\": \"desktop\",\n    \"recovery_mode\": \"auto\",\n}\n\nPLAYBOOK_TEMPLATES = {\n    \"grub_single\": {\n        \"title\": \"方式一：GRUB 单用户模式重置密码\",\n        \"kb_ref\": [\"SEC-001\", \"FAQ-忘记用户密码-方式①\"],\n        \"prerequisites\": [\n            \"需要虚拟机控制台访问权限（VMware/VirtualBox/物理显示器）\",\n            \"目标系统可正常进入 GRUB 引导菜单\",\n        ],\n        \"steps\": [\n            \"重启虚拟机，在银河麒麟 Logo 出现前连按 Esc 或 Shift，进入 GRUB 引导界面\",\n            \"选中默认启动项，按 e 进入编辑模式\",\n            \"找到以 linux 或 linuxefi 开头的行，在行末追加：rw init=/bin/bash\",\n            \"按 Ctrl+X 或 F10 使用当前配置启动，进入 root shell（单用户环境）\",\n            \"执行 mount -o remount,rw / 确保根分区可写（部分版本需要）\",\n            \"执行 passwd {username} 按提示输入新密码两次\",\n            \"（可选）若账户被锁定：faillock --user {username} --reset 或 pam_tally2 --user {username} --reset\",\n            \"执行 exec /sbin/init 或 reboot -f 重启系统\",\n            \"使用新密码在登录界面验证\",\n        ],\n        \"warnings\": [\n            \"禁止直接编辑 /etc/shadow 明文写入密码\",\n            \"操作前确认用户名正确，避免改错账户\",\n            \"桌面版与服务器版 GRUB 界面文字可能略有差异\",\n        ],\n    },\n    \"rescue\": {\n        \"title\": \"方式二：救援模式重置密码\",\n        \"kb_ref\": [\"KB-启动问题-救援模式\"],\n        \"prerequisites\": [\n            \"需要安装光盘/U盘启动介质或云平台救援镜像\",\n            \"知晓原系统根分区设备名（如 /dev/vda1、/dev/mapper/klas-root）\",\n        ],\n        \"steps\": [\n            \"使用麒麟安装光盘/U盘启动虚拟机，在引导菜单选择「救援模式」或 Troubleshooting → Rescue\",\n            \"选择「继续」以只读挂载原系统，或选择「读写挂载」\",\n            \"执行 chroot /mnt/sysimage 进入原系统环境（不同版本路径可能为 /mnt 或 /mnt/kylin）\",\n            \"执行 passwd {username} 修改目标用户密码\",\n            \"（可选）检查 /etc/selinux 配置，必要时 touch /.autorelabel\",\n            \"输入 exit 退出 chroot，重启并从硬盘启动\",\n            \"使用新密码登录验证\",\n        ],\n        \"warnings\": [\n            \"救援模式下误操作可能影响原系统引导，仅修改密码相关命令\",\n            \"chroot 路径因安装方式不同可能需人工确认\",\n        ],\n    },\n    \"livecd\": {\n        \"title\": \"方式三：LiveCD 模式重置密码（桌面版）\",\n        \"kb_ref\": [\"FAQ-忘记用户密码-方式②\", \"FAQ-忘记用户密码-方式③\"],\n        \"prerequisites\": [\n            \"适用于银河麒麟桌面版\",\n            \"需要光盘/U盘 LiveCD 启动介质\",\n            \"目前主要面向桌面系统场景\",\n        ],\n        \"steps\": [\n            \"将麒麟安装光盘放入光驱（或 U 盘引导），重启进入 LiveCD 桌面/命令行环境\",\n            \"打开终端，执行 lsblk 或 fdisk -l 确认原系统根分区挂载点\",\n            \"挂载原系统：mount /dev/<根分区> /mnt（按实际设备名替换）\",\n            \"（可选）chroot /mnt 进入原系统后执行 passwd {username}\",\n            \"或在 LiveCD 下使用 passwd 配合 chroot 修改密码\",\n            \"卸载分区 umount /mnt，退出 LiveCD 并从硬盘重启\",\n            \"若仅需备份数据：LiveCD 模式下拷贝 /home 等重要目录后再考虑系统还原\",\n            \"使用新密码登录验证\",\n        ],\n        \"warnings\": [\n            \"FAQ 提示：勿随意手工改写 /etc/shadow 字段，优先使用 passwd 命令\",\n            \"方式③可用于备份重要数据后还原系统，会覆盖现有系统\",\n            \"LiveCD 操作前确认挂载的是目标系统分区，避免误挂载\",\n        ],\n    },\n}\n\nSYSTEM_HINTS = {\n    \"desktop\": {\n        \"label\": \"银河麒麟桌面版\",\n        \"recommended_modes\": [\"grub_single\", \"livecd\", \"rescue\"],\n        \"notes\": \"桌面版优先尝试 GRUB 单用户；无法进入 GRUB 时使用 LiveCD。\",\n    },\n    \"server\": {\n        \"label\": \"银河麒麟服务器版\",\n        \"recommended_modes\": [\"grub_single\", \"rescue\"],\n        \"notes\": \"服务器版通常无图形 LiveCD 桌面，推荐 GRUB 单用户或安装介质救援模式。\",\n    },\n    \"kylin_v11\": {\n        \"label\": \"麒麟 V11 / KylinOS V11\",\n        \"recommended_modes\": [\"grub_single\", \"rescue\", \"livecd\"],\n        \"notes\": \"V11 可参考知识库 SEC-001：linux 行末加 rw init=/bin/bash 进入单用户。\",\n    },\n    \"auto\": {\n        \"label\": \"自动识别（默认桌面版流程）\",\n        \"recommended_modes\": [\"grub_single\", \"rescue\", \"livecd\"],\n        \"notes\": \"Agent 应根据 get_system_info 结果细化 system_type 后再次调用本工具。\",\n    },\n}\n\n\ndef _normalize_mode(mode: str) -> str:\n    m = (mode or \"auto\").strip().lower()\n    aliases = {\n        \"grub\": \"grub_single\",\n        \"single\": \"grub_single\",\n        \"single_user\": \"grub_single\",\n        \"rescue_mode\": \"rescue\",\n        \"live\": \"livecd\",\n        \"live_cd\": \"livecd\",\n    }\n    return aliases.get(m, m)\n\n\ndef _normalize_system_type(st: str) -> str:\n    s = (st or \"auto\").strip().lower()\n    if s in SYSTEM_HINTS:\n        return s\n    if \"server\" in s or \"服务器\" in s:\n        return \"server\"\n    if \"desktop\" in s or \"桌面\" in s:\n        return \"desktop\"\n    if \"v11\" in s or \"kylin\" in s:\n        return \"kylin_v11\"\n    return \"auto\"\n\n\ndef _build_playbook(username: str, mode: str) -> dict:\n    tpl = PLAYBOOK_TEMPLATES[mode]\n    steps = [step.format(username=username) for step in tpl[\"steps\"]]\n    return {\n        \"mode\": mode,\n        \"title\": tpl[\"title\"],\n        \"kb_ref\": tpl[\"kb_ref\"],\n        \"prerequisites\": tpl[\"prerequisites\"],\n        \"steps\": steps,\n        \"warnings\": tpl[\"warnings\"],\n        \"estimated_time_min\": 15 if mode == \"grub_single\" else 30,\n    }\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"目标用户\").strip()\n    system_type = _normalize_system_type(kwargs.get(\"system_type\") or kwargs.get(\"os_type\"))\n    recovery_mode = _normalize_mode(kwargs.get(\"recovery_mode\") or kwargs.get(\"mode\") or \"auto\")\n\n    if not username:\n        return {\"success\": False, \"error\": \"请提供 username 参数（需重置密码的用户名）\"}\n\n    sys_hint = SYSTEM_HINTS.get(system_type, SYSTEM_HINTS[\"auto\"])\n\n    if recovery_mode == \"auto\":\n        modes = sys_hint[\"recommended_modes\"]\n    elif recovery_mode in PLAYBOOK_TEMPLATES:\n        modes = [recovery_mode]\n    else:\n        return {\n            \"success\": False,\n            \"error\": f\"不支持的 recovery_mode: {recovery_mode}，可选: grub_single, rescue, livecd, auto\",\n        }\n\n    playbooks = [_build_playbook(username, m) for m in modes]\n\n    summary = (\n        f\"已为用户「{username}」生成 {len(playbooks)} 套离线密码恢复手册\"\n        f\"（{sys_hint[''label'']}）。\"\n        f\"请在虚拟机控制台按步骤操作，Agent 无法远程代替完成 GRUB/LiveCD 交互。\"\n    )\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"username\": username,\n            \"system_type\": system_type,\n            \"system_label\": sys_hint[\"label\"],\n            \"system_notes\": sys_hint[\"notes\"],\n            \"recovery_mode_requested\": recovery_mode,\n            \"playbooks\": playbooks,\n            \"agent_next_actions\": [\n                \"确认用户是否拥有虚拟机控制台（VNC/VMware 窗口）\",\n                \"若 SSH 仍可用且为其他管理员账号，优先建议在线改密而非离线流程\",\n                \"逐步引导用户执行手册，每步完成后请求反馈\",\n            ],\n            \"summary\": summary,\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- get_user_account_info (../../tools/custom/password_recovery/get_user_account_info.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('170ee2f8045a', 'get_user_account_info', '生成查询指定用户 UID、GID、家目录、登录 Shell、账户过期信息的远程命令。用于密码重置前确认目标用户存在且信息正确。', 'system_operation', 1, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：get_user_account_info — 查询指定 Linux 用户账户信息\"\"\"\nNAME = \"get_user_account_info\"\nDESCRIPTION = (\n    \"生成查询指定用户 UID、GID、家目录、登录 Shell、账户过期信息的远程命令。\"\n    \"用于密码重置前确认目标用户存在且信息正确。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 1\n\nTRIAL_ARGS = {\"username\": \"kylin\"}\n\n\ndef _cmds(username: str):\n    u = username.replace(\"''\", \"\")\n    return [\n        {\"command\": f\"getent passwd {u}\", \"purpose\": \"基础账户信息（用户:密码占位:UID:GID:描述:家目录:Shell）\"},\n        {\"command\": f\"id {u}\", \"purpose\": \"UID/GID 及所属组\"},\n        {\"command\": f\"chage -l {u} 2>/dev/null || echo ''chage-not-available''\", \"purpose\": \"密码过期与锁定策略\"},\n        {\"command\": f\"test -d $(getent passwd {u} | cut -d: -f6) && echo homedir-ok || echo homedir-missing\", \"purpose\": \"家目录是否存在\"},\n    ]\n\n\ndef _parse_hints():\n    return {\n        \"getent_missing\": \"用户不存在，请核对用户名或是否仅为系统用户\",\n        \"homedir_missing\": \"家目录缺失可能导致登录异常，重置密码后仍需修复目录\",\n        \"shell_nologin\": \"Shell 为 /sbin/nologin 时无法交互登录\",\n    }\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"\").strip()\n    if not username:\n        return {\"success\": False, \"error\": \"请提供 username 参数\"}\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"username\": username,\n            \"commands\": _cmds(username),\n            \"parse_hints\": _parse_hints(),\n            \"agent_instruction\": \"通过 execute_command 执行 commands，解析 getent passwd 输出字段\",\n            \"trial_simulated\": {\n                \"username\": username,\n                \"uid\": 1000,\n                \"home\": f\"/home/{username}\",\n                \"shell\": \"/bin/bash\",\n                \"exists\": True,\n            },\n            \"summary\": f\"已生成用户「{username}」账户信息查询命令\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- reset_user_password (../../tools/custom/password_recovery/reset_user_password.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('5014bbaf0662', 'reset_user_password', '生成在目标麒麟 VM 上通过 chpasswd 非交互重置指定用户密码的命令。禁止直接编辑 /etc/shadow；执行前需审批；密码须符合 get_password_policy 策略。', 'system_operation', 5, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：reset_user_password — 在线重置指定用户密码（需审批 L4~L5）\"\"\"\nNAME = \"reset_user_password\"\nDESCRIPTION = (\n    \"生成在目标麒麟 VM 上通过 chpasswd 非交互重置指定用户密码的命令。\"\n    \"禁止直接编辑 /etc/shadow；执行前需审批；密码须符合 get_password_policy 策略。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 5\n\nTRIAL_ARGS = {\n    \"username\": \"kylin\",\n    \"new_password\": \"Kylin@Temp2026!\",\n    \"dry_run\": True,\n}\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"\").strip()\n    new_password = kwargs.get(\"new_password\") or kwargs.get(\"password\") or \"\"\n    dry_run = bool(kwargs.get(\"dry_run\", False))\n\n    if not username:\n        return {\"success\": False, \"error\": \"请提供 username 参数\"}\n    if not new_password:\n        return {\"success\": False, \"error\": \"请提供 new_password 参数\"}\n\n    safe_user = username.replace(\"''\", \"\").replace(\":\", \"\")\n    # chpasswd 格式 user:password，密码中含 : 需转义或改用 passwd --stdin\n    escaped_pw = new_password.replace(\"''\", \"''\\\\''''\")\n    command = f\"echo ''{safe_user}:{escaped_pw}'' | chpasswd\"\n\n    audit_entry = {\n        \"action\": \"reset_user_password\",\n        \"username\": username,\n        \"method\": \"chpasswd\",\n        \"dry_run\": dry_run,\n        \"operator_note\": \"须记录工单号与审批人\",\n    }\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"risk_level\": RISK_LEVEL,\n            \"requires_approval\": True,\n            \"username\": username,\n            \"dry_run\": dry_run,\n            \"commands\": [\n                {\n                    \"command\": command,\n                    \"purpose\": \"通过 chpasswd 非交互重置密码\",\n                    \"forbidden\": \"禁止 sed/echo 直接写入 /etc/shadow\",\n                },\n            ],\n            \"alternative_commands\": [\n                {\n                    \"command\": f\"echo ''{escaped_pw}'' | passwd --stdin {safe_user}\",\n                    \"purpose\": \"部分旧系统可用 passwd --stdin\",\n                },\n            ],\n            \"audit\": audit_entry,\n            \"agent_instruction\": (\n                \"确认已完成 get_user_account_info、check_account_lock_status、get_password_policy；\"\n                \"获得 L4/L5 审批后通过 execute_command 执行；\"\n                \"dry_run=true 时仅返回命令不执行；执行后调用 verify_account_after_reset\"\n            ),\n            \"trial_simulated\": {\n                \"executed\": False,\n                \"dry_run\": dry_run,\n                \"message\": \"试运行模式：未实际改密，命令已生成\",\n            },\n            \"summary\": f\"已生成用户「{username}」密码重置命令（{''干跑'' if dry_run else ''待审批执行''}）\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;

-- verify_account_after_reset (../../tools/custom/password_recovery/verify_account_after_reset.py)
INSERT INTO tool_configs (id, name, description, category, risk_level, enabled, config_json, created_at, updated_at) VALUES ('0447a8b51761', 'verify_account_after_reset', '生成改密后验证命令：账户未锁定、getent 可查、家目录权限正常、shadow 状态有效。确认在线改密成功且用户可登录。', 'system_operation', 2, 1, '{"sourceType": "python", "sourceContent": "\"\"\"KylinOps 工具：verify_account_after_reset — 改密后验证账户状态\"\"\"\nNAME = \"verify_account_after_reset\"\nDESCRIPTION = (\n    \"生成改密后验证命令：账户未锁定、getent 可查、家目录权限正常、\"\n    \"shadow 状态有效。确认在线改密成功且用户可登录。\"\n)\nCATEGORY = \"system_operation\"\nRISK_LEVEL = 2\n\nTRIAL_ARGS = {\"username\": \"kylin\"}\n\n\ndef _cmds(username: str):\n    u = username.replace(\"''\", \"\")\n    return [\n        {\"command\": f\"getent passwd {u}\", \"purpose\": \"确认账户仍存在于 NSS\"},\n        {\"command\": f\"faillock --user {u} 2>/dev/null | tail -n +1 || echo ''faillock-ok-or-n/a''\", \"purpose\": \"确认未被 faillock 锁定\"},\n        {\"command\": f\"id {u}\", \"purpose\": \"确认 UID/GID 未变\"},\n        {\n            \"command\": (\n                f\"H=$(getent passwd {u} | cut -d: -f6); \"\n                f\"ls -ld \\\"$H\\\" 2>/dev/null || echo homedir-check-failed\"\n            ),\n            \"purpose\": \"家目录存在且权限合理（通常 drwx------ 或 drwxr-xr-x）\",\n        },\n        {\n            \"command\": f\"grep -E ''^{u}:'' /etc/shadow 2>/dev/null | cut -d: -f2 | head -c 5 || echo shadow-n/a\",\n            \"purpose\": \"shadow 哈希非空且非 !! 锁定占位\",\n        },\n    ]\n\n\ndef run(**kwargs):\n    username = (kwargs.get(\"username\") or kwargs.get(\"user\") or \"\").strip()\n    if not username:\n        return {\"success\": False, \"error\": \"请提供 username 参数\"}\n\n    return {\n        \"success\": True,\n        \"data\": {\n            \"tool\": NAME,\n            \"execution_mode\": \"remote_ssh\",\n            \"username\": username,\n            \"commands\": _cmds(username),\n            \"pass_criteria\": [\n                \"getent passwd 有输出\",\n                \"faillock 无失败记录或已 reset\",\n                \"家目录 ls -ld 成功\",\n                \"shadow 第二字段为 $ 开头的哈希而非 !! 或空\",\n            ],\n            \"on_failure\": {\n                \"locked\": \"执行 faillock --user {user} --reset\",\n                \"homedir\": \"检查家目录路径与属主 chown\",\n                \"shadow\": \"勿手改 shadow，重新执行 reset_user_password\",\n            },\n            \"agent_instruction\": \"reset_user_password 成功后执行本工具 commands，全部通过则告知用户用新密码登录\",\n            \"trial_simulated\": {\n                \"username\": username,\n                \"verified\": True,\n                \"checks_passed\": 4,\n            },\n            \"summary\": f\"已生成用户「{username}」改密后验证命令\",\n        },\n    }\n"}', '2026-06-13 14:00:43', '2026-06-13 14:00:43') ON CONFLICT (name) DO NOTHING;
